function minCostClimbingStairs(cost) {
  const memo = new Map();
  const reach = (i) => {                         // cheapest way to arrive at step i
    if (i <= 1) return 0;                        // you may start on step 0 or 1
    if (memo.has(i)) return memo.get(i);
    const best = Math.min(reach(i - 1) + cost[i - 1], reach(i - 2) + cost[i - 2]);
    memo.set(i, best);
    return best;
  };
  return reach(cost.length);                     // the top is past the last step
}

