int minCostClimbingStairs(int[] cost) {
    int twoBelow = 0, oneBelow = 0;              // reach[i - 2], reach[i - 1]
    for (int i = 2; i <= cost.length; i++) {
        int cur = Math.min(oneBelow + cost[i - 1], twoBelow + cost[i - 2]);
        twoBelow = oneBelow;
        oneBelow = cur;
    }
